import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        if (s == null) s = "";
        s = s.trim();

        int[] masks = new int[4];      // contagem via bitmask para C, E, U, P
        boolean[] dup = new boolean[4];
        String suits = "CEUP";

        for (int i = 0; i + 2 < s.length(); i += 3) {
            int val = (s.charAt(i) - '0') * 10 + (s.charAt(i + 1) - '0');
            int idx = suits.indexOf(s.charAt(i + 2));
            if (idx >= 0 && val >= 1 && val <= 13) {
                int bit = 1 << (val - 1);
                if ((masks[idx] & bit) != 0) dup[idx] = true;
                masks[idx] |= bit;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 4; i++) {
            if (dup[i]) sb.append("erro");
            else sb.append(13 - Integer.bitCount(masks[i]));
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
